Literal.Value:
'{
 "$schema": "https://vega.github.io/schema/vega/v5.json",
 "description": "Duas colunas por mes: mesmo mes do ano anterior (cinza, a esquerda) e mes atual (a direita). Mes atual maior que o ano anterior = azul de destaque; menor = verde; sem base de comparacao = cinza claro. O signal tolerancia (0 = estrito; 0.02 = +-2%) define a faixa de empate.",
 "padding": 0,
 "config": {
  "view": {
   "stroke": null
  },
  "text": {
   "font": "Din"
  }
 },
 "data": [
  {
   "name": "dataset"
  },
  {
   "name": "series",
   "source": "dataset",
   "transform": [
    {
     "type": "formula",
     "as": "label",
     "expr": "datum[''Mês/Ano'']"
    },
    {
     "type": "formula",
     "as": "ord",
     "expr": "datum[''Ano Mês Num'']"
    },
    {
     "type": "formula",
     "as": "focos",
     "expr": "datum[''Total de Focos'']"
    },
    {
     "type": "formula",
     "as": "prev",
     "expr": "datum[''Focos Ano Anterior'']"
    },
    {
     "type": "formula",
     "as": "var",
     "expr": "datum[''Variação Ano Anterior %'']"
    },
    {
     "type": "filter",
     "expr": "isValid(datum.focos) && isValid(datum.ord)"
    },
    {
     "type": "collect",
     "sort": {
      "field": "ord",
      "order": "ascending"
     }
    },
    {
     "type": "window",
     "ops": [
      "row_number"
     ],
     "as": [
      "idx"
     ]
    },
    {
     "type": "formula",
     "as": "month",
     "expr": "datum.ord % 100"
    },
    {
     "type": "formula",
     "as": "hasPrev",
     "expr": "isValid(datum.prev) && isValid(datum.var)"
    },
    {
     "type": "formula",
     "as": "status",
     "expr": "!datum.hasPrev ? ''na'' : (datum.var < -tolerancia ? ''better'' : (datum.var > tolerancia ? ''worse'' : ''same''))"
    },
    {
     "type": "formula",
     "as": "barColor",
     "expr": "datum.status === ''better'' ? cBetter : (datum.status === ''worse'' ? cAccent : cNeutral)"
    },
    {
     "type": "formula",
     "as": "barOpacityK",
     "expr": "datum.status === ''na'' ? 0.2 : 1"
    },
    {
     "type": "formula",
     "as": "statusText",
     "expr": "datum.status === ''better'' ? ''Menor que o ano anterior (melhor)'' : (datum.status === ''worse'' ? ''Maior que o ano anterior'' : (datum.status === ''same'' ? ''Estável'' : ''Sem base de comparação''))"
    },
    {
     "type": "formula",
     "as": "yMax",
     "expr": "max(datum.focos, datum.hasPrev ? datum.prev : 0)"
    },
    {
     "type": "formula",
     "as": "isBetter",
     "expr": "datum.status === ''better'' ? 1 : 0"
    },
    {
     "type": "formula",
     "as": "isCmp",
     "expr": "datum.hasPrev ? 1 : 0"
    }
   ]
  },
  {
   "name": "sum",
   "source": "series",
   "transform": [
    {
     "type": "aggregate",
     "fields": [
      "isBetter",
      "isCmp"
     ],
     "ops": [
      "sum",
      "sum"
     ],
     "as": [
      "nBetter",
      "nCmp"
     ]
    }
   ]
  },
  {
   "name": "legend",
   "values": [
    {
     "t": "Mês atual menor",
     "s": "Atual menor",
     "k": "better"
    },
    {
     "t": "Mês atual maior",
     "s": "Atual maior",
     "k": "worse"
    },
    {
     "t": "Ano anterior",
     "s": "Ano anterior",
     "k": "prev"
    },
    {
     "t": "Sem comparação",
     "s": "Sem base",
     "k": "na"
    }
   ],
   "transform": [
    {
     "type": "formula",
     "as": "txt",
     "expr": "innerW < 470 ? datum.s : datum.t"
    },
    {
     "type": "formula",
     "as": "w",
     "expr": "length(datum.txt) * fsMicro * 0.6 + 30"
    },
    {
     "type": "window",
     "ops": [
      "sum"
     ],
     "fields": [
      "w"
     ],
     "as": [
      "cum"
     ],
     "frame": [
      null,
      0
     ]
    },
    {
     "type": "formula",
     "as": "x",
     "expr": "datum.cum - datum.w"
    },
    {
     "type": "formula",
     "as": "fits",
     "expr": "datum.x + datum.w <= innerW && nSeries > 0"
    }
   ]
  },
  {
   "name": "yticks",
   "transform": [
    {
     "type": "sequence",
     "start": 0,
     "stop": {
      "signal": "nSeries > 0 ? floor(yMaxDom / yStep) + 1 : 0"
     },
     "step": 1,
     "as": "i"
    },
    {
     "type": "formula",
     "as": "v",
     "expr": "datum.i * yStep"
    }
   ]
  },
  {
   "name": "emptyState",
   "values": [
    {
     "k": 1
    }
   ],
   "transform": [
    {
     "type": "filter",
     "expr": "length(data(''series'')) === 0"
    }
   ]
  }
 ],
 "signals": [
  {
   "name": "cText",
   "value": "#F4F6F8"
  },
  {
   "name": "cTextMuted",
   "value": "#AEB6C2"
  },
  {
   "name": "cSurface",
   "value": "#15191F"
  },
  {
   "name": "cSurface2",
   "value": "#1D232B"
  },
  {
   "name": "cBorder",
   "value": "#2A323C"
  },
  {
   "name": "cBetter",
   "value": "#3DDC97"
  },
  {
   "name": "cAccent",
   "value": "#5BC0EB"
  },
  {
   "name": "cPrevBar",
   "value": "#667385"
  },
  {
   "name": "cNeutral",
   "value": "#9AA5B1"
  },
  {
   "name": "tolerancia",
   "value": 0
  },
  {
   "name": "hovOrd",
   "value": null,
   "on": [
    {
     "events": "@hit:mouseover",
     "update": "datum.ord"
    },
    {
     "events": "@hit:mouseout",
     "update": "null"
    }
   ]
  },
  {
   "name": "fs",
   "update": "max(0.8, min(1.15, min(width / 560, height / 320)))"
  },
  {
   "name": "pad",
   "update": "max(12, min(20, width * 0.035))"
  },
  {
   "name": "radius",
   "update": "max(10, min(18, height * 0.08))"
  },
  {
   "name": "fsTitle",
   "update": "max(10.5, 11 * fs)"
  },
  {
   "name": "fsMicro",
   "update": "max(10, 10.5 * fs)"
  },
  {
   "name": "innerW",
   "update": "max(0, width - 2 * pad)"
  },
  {
   "name": "nSeries",
   "update": "length(data(''series''))"
  },
  {
   "name": "showFooter",
   "update": "height >= 200"
  },
  {
   "name": "footerH",
   "update": "showFooter ? fsMicro + 12 : 0"
  },
  {
   "name": "legendY",
   "update": "pad + fsTitle + 8"
  },
  {
   "name": "topY",
   "update": "legendY + fsMicro + 16"
  },
  {
   "name": "xAxisH",
   "update": "fsMicro + 10"
  },
  {
   "name": "axisW",
   "update": "max(36, 46 * fs)"
  },
  {
   "name": "x0",
   "update": "pad + axisW"
  },
  {
   "name": "x1",
   "update": "max(x0 + 40, width - pad)"
  },
  {
   "name": "y0",
   "update": "topY"
  },
  {
   "name": "y1",
   "update": "max(y0 + 30, height - pad - footerH - xAxisH)"
  },
  {
   "name": "bandStep",
   "update": "(x1 - x0) / max(1, nSeries)"
  },
  {
   "name": "bw",
   "update": "bandwidth(''x'')"
  },
  {
   "name": "labelEvery",
   "update": "bandStep >= 64 ? 1 : (bandStep * 3 >= 64 ? 3 : (bandStep * 6 >= 64 ? 6 : 12))"
  },
  {
   "name": "yMaxDom",
   "update": "nSeries > 0 ? domain(''y'')[1] : 1"
  },
  {
   "name": "yRaw",
   "update": "max(1, yMaxDom) / 4"
  },
  {
   "name": "yPow",
   "update": "pow(10, floor(log(yRaw) / LN10))"
  },
  {
   "name": "yStep",
   "update": "(yRaw / yPow <= 1 ? 1 : (yRaw / yPow <= 2 ? 2 : (yRaw / yPow <= 5 ? 5 : 10))) * yPow"
  }
 ],
 "scales": [
  {
   "name": "x",
   "type": "band",
   "paddingInner": 0.2,
   "paddingOuter": 0.05,
   "domain": {
    "data": "series",
    "field": "ord"
   },
   "range": [
    {
     "signal": "x0"
    },
    {
     "signal": "x1"
    }
   ]
  },
  {
   "name": "g",
   "type": "band",
   "padding": 0.06,
   "domain": [
    "prev",
    "cur"
   ],
   "range": [
    0,
    {
     "signal": "bw"
    }
   ]
  },
  {
   "name": "y",
   "type": "linear",
   "zero": true,
   "nice": true,
   "domain": {
    "data": "series",
    "field": "yMax"
   },
   "range": [
    {
     "signal": "y1"
    },
    {
     "signal": "y0"
    }
   ]
  }
 ],
 "marks": [
  {
   "name": "shadow",
   "type": "rect",
   "encode": {
    "update": {
     "x": {
      "value": 3
     },
     "y": {
      "value": 3
     },
     "width": {
      "signal": "max(0, width - 3)"
     },
     "height": {
      "signal": "max(0, height - 3)"
     },
     "cornerRadius": {
      "signal": "radius"
     },
     "fill": {
      "value": "#000000"
     },
     "fillOpacity": {
      "value": 0.28
     }
    }
   }
  },
  {
   "name": "surface",
   "type": "rect",
   "encode": {
    "update": {
     "x": {
      "value": 0
     },
     "y": {
      "value": 0
     },
     "width": {
      "signal": "max(0, width - 3)"
     },
     "height": {
      "signal": "max(0, height - 3)"
     },
     "cornerRadius": {
      "signal": "radius"
     },
     "fill": {
      "signal": "cSurface"
     },
     "stroke": {
      "signal": "cBorder"
     },
     "strokeWidth": {
      "value": 1
     }
    }
   }
  },
  {
   "name": "title",
   "type": "text",
   "encode": {
    "update": {
     "x": {
      "signal": "pad"
     },
     "y": {
      "signal": "pad"
     },
     "text": {
      "signal": "innerW < 400 ? ''ATUAL vs. ANO ANTERIOR'' : ''FOCOS POR MÊS: ATUAL vs. MESMO MÊS DO ANO ANTERIOR''"
     },
     "baseline": {
      "value": "top"
     },
     "fill": {
      "signal": "cTextMuted"
     },
     "fontSize": {
      "signal": "fsTitle"
     },
     "fontWeight": {
      "value": 600
     },
     "limit": {
      "signal": "innerW"
     }
    }
   }
  },
  {
   "name": "legendSwatch",
   "type": "rect",
   "from": {
    "data": "legend"
   },
   "interactive": false,
   "encode": {
    "update": {
     "x": {
      "signal": "pad + datum.x"
     },
     "y": {
      "signal": "legendY + 1"
     },
     "width": {
      "value": 10
     },
     "height": {
      "value": 10
     },
     "cornerRadius": {
      "value": 2
     },
     "fill": {
      "signal": "datum.k === ''better'' ? cBetter : (datum.k === ''worse'' ? cAccent : (datum.k === ''na'' ? cNeutral : cPrevBar))"
     },
     "fillOpacity": {
      "signal": "datum.fits ? (datum.k === ''na'' ? 0.2 : 0.92) : 0"
     },
     "stroke": {
      "signal": "cNeutral"
     },
     "strokeWidth": {
      "signal": "datum.k === ''na'' ? 1.2 : 0"
     },
     "strokeOpacity": {
      "signal": "datum.fits ? 0.9 : 0"
     }
    }
   }
  },
  {
   "name": "legendText",
   "type": "text",
   "from": {
    "data": "legend"
   },
   "interactive": false,
   "encode": {
    "update": {
     "x": {
      "signal": "pad + datum.x + 16"
     },
     "y": {
      "signal": "legendY + 6"
     },
     "text": {
      "signal": "datum.fits ? datum.txt : ''''"
     },
     "baseline": {
      "value": "middle"
     },
     "fill": {
      "signal": "cTextMuted"
     },
     "fontSize": {
      "signal": "fsMicro"
     }
    }
   }
  },
  {
   "name": "gridLines",
   "type": "rule",
   "from": {
    "data": "yticks"
   },
   "interactive": false,
   "encode": {
    "update": {
     "x": {
      "signal": "x0"
     },
     "x2": {
      "signal": "x1"
     },
     "y": {
      "signal": "scale(''y'', datum.v)"
     },
     "stroke": {
      "signal": "cBorder"
     },
     "strokeOpacity": {
      "signal": "datum.i === 0 ? 0 : 0.8"
     },
     "strokeWidth": {
      "value": 1
     }
    }
   }
  },
  {
   "name": "yLabels",
   "type": "text",
   "from": {
    "data": "yticks"
   },
   "interactive": false,
   "encode": {
    "update": {
     "x": {
      "signal": "x0 - 8"
     },
     "y": {
      "signal": "scale(''y'', datum.v)"
     },
     "text": {
      "signal": "datum.i === 0 ? ''0'' : (datum.v >= 1000000 ? pbiFormat(datum.v / 1000000, datum.v % 1000000 === 0 ? ''#,0'' : ''#,0.0'') + '' Mi'' : (datum.v >= 1000 ? pbiFormat(datum.v / 1000, ''#,0'') + '' Mil'' : pbiFormat(datum.v, ''#,0'')))"
     },
     "align": {
      "value": "right"
     },
     "baseline": {
      "value": "middle"
     },
     "fill": {
      "signal": "cTextMuted"
     },
     "fontSize": {
      "signal": "fsMicro"
     }
    }
   }
  },
  {
   "name": "prevBars",
   "type": "rect",
   "from": {
    "data": "series"
   },
   "interactive": false,
   "encode": {
    "update": {
     "x": {
      "signal": "scale(''x'', datum.ord) + scale(''g'', ''prev'')"
     },
     "width": {
      "signal": "bandwidth(''g'')"
     },
     "y": {
      "signal": "datum.hasPrev ? scale(''y'', datum.prev) : y1"
     },
     "y2": {
      "signal": "y1"
     },
     "cornerRadiusTopLeft": {
      "value": 2
     },
     "cornerRadiusTopRight": {
      "value": 2
     },
     "fill": {
      "signal": "cPrevBar"
     },
     "fillOpacity": {
      "signal": "datum.hasPrev ? (datum.__selected__ === ''off'' ? 0.3 : (hovOrd !== null && hovOrd !== datum.ord ? 0.55 : 0.92)) : 0"
     }
    }
   }
  },
  {
   "name": "curBars",
   "type": "rect",
   "from": {
    "data": "series"
   },
   "interactive": false,
   "encode": {
    "update": {
     "x": {
      "signal": "scale(''x'', datum.ord) + scale(''g'', ''cur'')"
     },
     "width": {
      "signal": "bandwidth(''g'')"
     },
     "y": {
      "scale": "y",
      "field": "focos"
     },
     "y2": {
      "signal": "y1"
     },
     "cornerRadiusTopLeft": {
      "value": 2
     },
     "cornerRadiusTopRight": {
      "value": 2
     },
     "fill": {
      "field": "barColor"
     },
     "fillOpacity": {
      "signal": "(datum.__selected__ === ''off'' ? 0.3 : (hovOrd !== null && hovOrd !== datum.ord ? 0.55 : 0.92)) * datum.barOpacityK"
     },
     "stroke": {
      "signal": "cNeutral"
     },
     "strokeWidth": {
      "signal": "datum.status === ''na'' ? 1.2 : 0"
     },
     "strokeOpacity": {
      "signal": "datum.__selected__ === ''off'' ? 0.3 : 0.9"
     }
    }
   }
  },
  {
   "name": "baseline",
   "type": "rule",
   "interactive": false,
   "encode": {
    "update": {
     "x": {
      "signal": "x0"
     },
     "x2": {
      "signal": "x1"
     },
     "y": {
      "signal": "y1"
     },
     "stroke": {
      "signal": "cTextMuted"
     },
     "strokeOpacity": {
      "signal": "nSeries > 0 ? 0.5 : 0"
     }
    }
   }
  },
  {
   "name": "xLabels",
   "type": "text",
   "from": {
    "data": "series"
   },
   "interactive": false,
   "encode": {
    "update": {
     "x": {
      "signal": "scale(''x'', datum.ord) + bw / 2"
     },
     "y": {
      "signal": "y1 + 8"
     },
     "text": {
      "signal": "((datum.month - 1) % labelEvery === 0) ? datum.label : ''''"
     },
     "align": {
      "value": "center"
     },
     "baseline": {
      "value": "top"
     },
     "fill": {
      "signal": "cTextMuted"
     },
     "fontSize": {
      "signal": "fsMicro"
     }
    }
   }
  },
  {
   "name": "hit",
   "type": "rect",
   "from": {
    "data": "series"
   },
   "encode": {
    "enter": {
     "fill": {
      "value": "#FFFFFF"
     },
     "cursor": {
      "value": "pointer"
     }
    },
    "update": {
     "x": {
      "signal": "scale(''x'', datum.ord) - (bandStep - bw) / 2"
     },
     "width": {
      "signal": "bandStep"
     },
     "y": {
      "signal": "y0"
     },
     "y2": {
      "signal": "y1"
     },
     "fillOpacity": {
      "value": 0
     },
     "tooltip": {
      "signal": "{''Período'': datum.label, ''Focos'': pbiFormat(datum.focos, ''#,0''), ''Mesmo mês do ano anterior'': datum.hasPrev ? pbiFormat(datum.prev, ''#,0'') : ''sem dados'', ''Diferença'': datum.hasPrev ? pbiFormat(datum.focos - datum.prev, ''+#,0;-#,0;0'') : ''—'', ''Variação'': datum.hasPrev ? pbiFormat(datum.var, ''+0.0%;-0.0%;0.0%'') : ''—'', ''Avaliação'': datum.statusText}"
     }
    },
    "hover": {
     "fillOpacity": {
      "value": 0.05
     }
    }
   }
  },
  {
   "name": "footer",
   "type": "text",
   "from": {
    "data": "sum"
   },
   "interactive": false,
   "encode": {
    "update": {
     "x": {
      "signal": "pad"
     },
     "y": {
      "signal": "height - pad - 3"
     },
     "text": {
      "signal": "showFooter ? (datum.nCmp > 0 ? (innerW < 380 ? ''Menos focos em '' : ''Menos focos que o ano anterior em '') + datum.nBetter + '' de '' + datum.nCmp + (innerW < 380 ? '' meses ('' : '' meses comparáveis ('') + pbiFormat(datum.nBetter / datum.nCmp, ''0.0%'') + '')'' : ''Sem base de comparação no período selecionado'') : ''''"
     },
     "baseline": {
      "value": "bottom"
     },
     "fill": {
      "signal": "cTextMuted"
     },
     "fontSize": {
      "signal": "fsMicro"
     },
     "limit": {
      "signal": "innerW"
     }
    }
   }
  },
  {
   "name": "emptyMessage",
   "type": "text",
   "from": {
    "data": "emptyState"
   },
   "interactive": false,
   "encode": {
    "update": {
     "x": {
      "signal": "width / 2"
     },
     "y": {
      "signal": "height / 2"
     },
     "text": {
      "value": "Sem dados para o contexto selecionado"
     },
     "align": {
      "value": "center"
     },
     "baseline": {
      "value": "middle"
     },
     "fill": {
      "signal": "cTextMuted"
     },
     "fontSize": {
      "signal": "max(12, 14 * fs)"
     },
     "limit": {
      "signal": "max(0, width - 2 * pad)"
     }
    }
   }
  }
 ]
}'

'{
  "autosize": {
    "contains": "padding",
    "type": "fit"
  },
  "view": {
    "stroke": "transparent"
  },
  "font": "Segoe UI, wf_segoe-ui_normal, helvetica, arial, sans-serif",
  "arc": {},
  "area": {
    "line": true,
    "opacity": 0.6
  },
  "bar": {},
  "line": {
    "strokeWidth": 3,
    "strokeCap": "round",
    "strokeJoin": "round"
  },
  "point": {
    "filled": true,
    "size": 75
  },
  "rect": {},
  "text": {
    "font": "Segoe UI, wf_segoe-ui_normal, helvetica, arial, sans-serif",
    "fontSize": 12,
    "fill": "#616161"
  },
  "axis": {
    "ticks": false,
    "grid": false,
    "domain": false,
    "labelColor": "#616161",
    "labelFontSize": 12,
    "titleFont": "din, wf_standard-font, helvetica, arial, sans-serif",
    "titleColor": "#242424",
